void BZ2_blockSort ( EState* s ) {
   UInt32* ptr = s->ptr;
   UChar* block = s->block;
   UInt32* ftab = s->ftab;
   Int32 nblock = s->nblock;
   Int32 verb = s->verbosity;
   Int32 wfact = s->workFactor;
   UInt16* quadrant;
   Int32 budget;
   Int32 budgetInit;
   Int32 i;
   if (nblock < 10000) {
      fallbackSort ( s->arr1, s->arr2, ftab, nblock, verb );
   } else {
      i = nblock+(2 + 12 + 18 + 2);
      if (i & 1) i++;
      quadrant = (UInt16*)(&(block[i]));
      if (wfact < 1 ) wfact = 1;
      if (wfact > 100) wfact = 100;
      budgetInit = nblock * ((wfact-1) / 3);
      budget = budgetInit;
      mainSort ( ptr, block, quadrant, ftab, nblock, verb, &budget );
      if (verb >= 3) fprintf(stderr,"      %d work, %d block, ratio %5.2f\n",budgetInit - budget,nblock,(float)(budgetInit - budget) / (float)(nblock==0 ? 1 : nblock));
      if (budget < 0) {
         if (verb >= 2) fprintf(stderr,"    too repetitive; using fallback" " sorting algorithm\n");
         fallbackSort ( s->arr1, s->arr2, ftab, nblock, verb );
      }
   }
   s->origPtr = -1;
   for (i = 0; i < s->nblock; i++) if (ptr[i] == 0) { s->origPtr = i; break; };
   { if (!(s->origPtr != -1)) BZ2_bz__AssertH__fail ( 1003 ); };
}

static __inline__ void fallbackSimpleSort ( UInt32* fmap, UInt32* eclass, Int32 lo, Int32 hi ) {
   Int32 i, j, tmp;
   UInt32 ec_tmp;
   if (lo == hi) return;
   if (hi - lo > 3) {
      for ( i = hi-4; i >= lo; i-- ) {
         tmp = fmap[i];
         ec_tmp = eclass[tmp];
         for ( j = i+4; j <= hi && ec_tmp > eclass[fmap[j]]; j += 4 ) fmap[j-4] = fmap[j];
         fmap[j-4] = tmp;
      }
   }
   for ( i = hi-1; i >= lo; i-- ) {
      tmp = fmap[i];
      ec_tmp = eclass[tmp];
      for ( j = i+1; j <= hi && ec_tmp > eclass[fmap[j]]; j++ ) fmap[j-1] = fmap[j];
      fmap[j-1] = tmp;
   }
}

