void panic ( const Char* s ) {
   fprintf ( stderr, "
%s: PANIC -- internal consistency error:
" "	%s
" "	This is a BUG.  Please report it to:
" "	bzip2-devel@sourceware.org
", progName, s );
   showFileNames();
   cleanUpAndFail( 3 );
}

