   fprintf ( stderr, "bzip2: I'm not configured correctly for this platform!
" "	I require Int32, Int16 and Char to have sizes
" "	of 4, 2 and 1 bytes to run properly, and they don't.
" "	Probably you can fix this by defining them correctly,
" "	and recompiling.  Bye!
" );
   setExit(3);
   exit(exitValue);
}

void crcError ( void ) {
   fprintf ( stderr, "\n%s: Data integrity error when decompressing.\n", progName );
   showFileNames();
   cadvise();
   cleanUpAndFail( 2 );
}

void cleanUpAndFail ( Int32 ec ) {
   IntNative retVal;
   struct stat statBuf;
   if ( srcMode == 3 && opMode != 3 && deleteOutputOnInterrupt ) {
      retVal = stat ( inName, &statBuf );
      if (retVal == 0) {
         if (noisy) fprintf ( stderr, "%s: Deleting output file %s, if it exists.\n", progName, outName );
         if (outputHandleJustInCase != ((void*)0)) fclose ( outputHandleJustInCase );
         retVal = remove ( outName );
         if (retVal != 0) fprintf ( stderr, "%s: WARNING: deletion of output file " "(apparently) failed.\n", progName );
      } else {
         fprintf ( stderr, "%s: WARNING: deletion of output file suppressed\n", progName );
         fprintf ( stderr, "%s:    since input file no longer exists.  Output file\n", progName );
         fprintf ( stderr, "%s:    `%s' may be incomplete.\n", progName, outName );
         fprintf ( stderr, "%s:    I suggest doing an integrity test (bzip2 -tv)" " of it.\n", progName );
