   if ( strlen(from) > 1034 -10 ) {
      fprintf ( stderr, "bzip2: file name\n`%s'\n" "is suspiciously (more than %d chars) long.\n" "Try using a reasonable file name instead.  Sorry! :-)\n", from, 1034 -10 );
      setExit(1);
      exit(exitValue);
   }
  strncpy(to,from,1034 -10);
  to[1034 -10]='\0';
}

