   double base = 1.0;
   double sum = 0.0;
   for (i = 0; i < 8; i++) {
      sum += base * (double)(n->b[i]);
      base *= 256.0;
   }
   return sum;
}

Bool uInt64_isZero ( UInt64* n ) {
   Int32 i;
   for (i = 0; i < 8; i++) if (n->b[i] != 0) return 0;
   return 1;
}

Int32 uInt64_qrm10 ( UInt64* n ) {
   UInt32 rem, tmp;
   Int32 i;
   rem = 0;
   for (i = 7; i >= 0; i--) {
      tmp = rem * 256 + n->b[i];
      n->b[i] = tmp / 10;
      rem = tmp % 10;
   }
   return rem;
}

void uInt64_toAscii ( char* outbuf, UInt64* n ) {
   Int32 i, q;
   UChar buf[32];
   Int32 nBuf = 0;
   UInt64 n_copy = *n;
   do {
      q = uInt64_qrm10 ( &n_copy );
      buf[nBuf] = q + '0';
      nBuf++;
   } while (!uInt64_isZero(&n_copy));
   outbuf[nBuf] = 0;
   for (i = 0; i < nBuf; i++) outbuf[i] = buf[nBuf-i-1];
}

